**What this code covers**

- Document database mock: in-memory JSON document store with collections, JSON-based query language, B-tree-style indexes, and an aggregation pipeline…
- Get a value at a dot-notation path: 'author.name' -> doc['author']['name'].
- Evaluate a MongoDB-style query against a document.
- A MongoDB-style collection of JSON documents.
- Array membership: check if any element has this field
- Operator query: {field: {$gt: 30, $lt: 50}}
- Match if val is in the list (array membership) OR equals list
- Direct equality (also matches if val is a list containing cond)

**Defines:** `_get_nested()`, `_match()`, `Collection`, `_set_nested()`, `DocumentDB`

```python
"""
Document database mock: in-memory JSON document store with collections,
JSON-based query language, B-tree-style indexes, and an aggregation
pipeline (subset of MongoDB's API).

Demonstrates:
  - Collections of heterogeneous JSON documents
  - JSON-based query language (operators: $gt, $lt, $in, $or, $and, $regex)
  - Nested field access via dot notation (author.name)
  - Array membership queries (tags: "tech")
  - Single + compound indexes (B-tree emulation via sorted dict)
  - Aggregation pipeline ($match, $group, $sort, $project, $limit)
  - Schemaless: per-document fields, no enforcement (cautionary tale)

Models a simplified MongoDB-style document store.

Run:  python3 document_db.py
"""

import re
import time
import json
import bisect
from collections import defaultdict, OrderedDict
from typing import Any, Dict, List, Optional, Callable

def _get_nested(doc: dict, path: str) -> Any:
    """Get a value at a dot-notation path: 'author.name' -> doc['author']['name']."""
    cur = doc
    for part in path.split("."):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        elif isinstance(cur, list):
            # Array membership: check if any element has this field
            return [elem.get(part) if isinstance(elem, dict) else None
                    for elem in cur]
        else:
            return None
    return cur

def _match(doc: dict, query: dict) -> bool:
    """Evaluate a MongoDB-style query against a document."""
    for field, cond in query.items():
        if field == "$or":
            if not any(_match(doc, sub) for sub in cond):
                return False
        elif field == "$and":
            if not all(_match(doc, sub) for sub in cond):
                return False
        else:
            val = _get_nested(doc, field)
            if isinstance(cond, dict) and any(k.startswith("$") for k in cond):
                # Operator query: {field: {$gt: 30, $lt: 50}}
                for op, target in cond.items():
                    if op == "$gt" and not (val is not None and val > target):
                        return False
                    elif op == "$gte" and not (val is not None and val >= target):
                        return False
                    elif op == "$lt" and not (val is not None and val < target):
                        return False
                    elif op == "$lte" and not (val is not None and val <= target):
                        return False
                    elif op == "$eq" and not (val == target):
                        return False
                    elif op == "$ne" and not (val != target):
                        return False
                    elif op == "$in" and not (val in target):
                        return False
                    elif op == "$nin" and not (val not in target):
                        return False
                    elif op == "$regex":
                        if not (isinstance(val, str)
                                and re.search(target, val)):
                            return False
            elif isinstance(cond, list):
                # Match if val is in the list (array membership) OR equals list
                if val != cond and not (isinstance(val, list) and
                                        set(cond).issubset(set(val))) \
                   and val not in cond:
                    return False
            else:
                # Direct equality (also matches if val is a list containing cond)
                if val != cond and not (isinstance(val, list) and cond in val):
                    return False
    return True

class Collection:
    """A MongoDB-style collection of JSON documents."""

    def __init__(self, name: str):
        self.name = name
        self._docs: OrderedDict[str, dict] = OrderedDict()  # _id -> doc
        self._indexes: Dict[str, Dict[Any, List[str]]] = {}
        # _indexes[field_path] = {value: [_id, _id, ...]}

    def insert(self, doc: dict) -> str:
        """Insert a document. Auto-generates _id if missing."""
        if "_id" not in doc:
            doc["_id"] = f"oid_{int(time.time()*1000)}_{len(self._docs)}"
        doc_id = str(doc["_id"])
        if doc_id in self._docs:
            raise ValueError(f"Duplicate _id: {doc_id}")
        self._docs[doc_id] = doc
        # Update indexes
        for field in self._indexes:
            val = _get_nested(doc, field)
            if val is not None:
                if isinstance(val, list):
                    for v in val:
                        self._indexes[field].setdefault(v, []).append(doc_id)
                else:
                    self._indexes[field].setdefault(val, []).append(doc_id)
        return doc_id

    def find(self, query: Optional[dict] = None, limit: int = 0) -> List[dict]:
        """Find documents matching query. Uses index if available."""
        if not query:
            results = list(self._docs.values())
            return results[:limit] if limit else results
        # Check if query can use an index (single-field equality)
        if len(query) == 1 and not any(k.startswith("$") for k in query):
            field, cond = next(iter(query.items()))
            if field in self._indexes and not isinstance(cond, dict):
                idx = self._indexes[field]
                if isinstance(cond, list):
                    ids = []
                    for v in cond:
                        ids.extend(idx.get(v, []))
                else:
                    ids = idx.get(cond, [])
                results = [self._docs[i] for i in ids]
                return results[:limit] if limit else results
        # Fallback: collection scan (COLLSCAN)
        results = [d for d in self._docs.values() if _match(d, query)]
        return results[:limit] if limit else results

    def find_one(self, query: dict) -> Optional[dict]:
        results = self.find(query, limit=1)
        return results[0] if results else None

    def update(self, query: dict, update: dict) -> int:
        """Update matching docs. Supports $set, $inc, $push."""
        count = 0
        for doc in self.find(query):
            for op, fields in update.items():
                if op == "$set":
                    for k, v in fields.items():
                        _set_nested(doc, k, v)
                elif op == "$inc":
                    for k, v in fields.items():
                        cur = _get_nested(doc, k) or 0
                        _set_nested(doc, k, cur + v)
                elif op == "$push":
                    for k, v in fields.items():
                        arr = _get_nested(doc, k) or []
                        arr.append(v)
                        _set_nested(doc, k, arr)
            count += 1
        return count

    def delete(self, query: dict) -> int:
        """Delete matching docs."""
        to_delete = [d["_id"] for d in self.find(query)]
        for doc_id in to_delete:
            del self._docs[str(doc_id)]
        return len(to_delete)

    def create_index(self, field: str) -> str:
        """Create an index on a field (or nested path)."""
        if field in self._indexes:
            return field
        idx: Dict[Any, List[str]] = defaultdict(list)
        for doc_id, doc in self._docs.items():
            val = _get_nested(doc, field)
            if val is not None:
                if isinstance(val, list):
                    for v in val:
                        idx[v].append(doc_id)
                else:
                    idx[val].append(doc_id)
        self._indexes[field] = idx
        return field

    def aggregate(self, pipeline: List[dict]) -> List[dict]:
        """Run an aggregation pipeline: $match, $group, $sort, $project, $limit."""
        docs = list(self._docs.values())
        for stage in pipeline:
            if "$match" in stage:
                docs = [d for d in docs if _match(d, stage["$match"])]
            elif "$group" in stage:
                spec = stage["$group"]
                gid_expr = spec["_id"]  # field path like "$author.name"
                groups: Dict[Any, List[dict]] = defaultdict(list)
                for d in docs:
                    if isinstance(gid_expr, str) and gid_expr.startswith("$"):
                        key = _get_nested(d, gid_expr[1:])
                    else:
                        key = gid_expr
                    groups[str(key)].append(d)
                out = []
                for key, group_docs in groups.items():
                    result = {"_id": key}
                    for field, expr in spec.items():
                        if field == "_id":
                            continue
                        if isinstance(expr, dict) and "$sum" in expr:
                            arg = expr["$sum"]
                            if arg == 1:
                                result[field] = len(group_docs)
                            else:
                                result[field] = sum(
                                    _get_nested(d, arg[1:]) or 0
                                    for d in group_docs
                                ) if isinstance(arg, str) else arg * len(group_docs)
                        elif isinstance(expr, dict) and "$avg" in expr:
                            arg = expr["$avg"][1:]
                            vals = [_get_nested(d, arg) or 0 for d in group_docs]
                            result[field] = sum(vals) / len(vals) if vals else 0
                        elif isinstance(expr, dict) and "$push" in expr:
                            arg = expr["$push"][1:]
                            result[field] = [_get_nested(d, arg) for d in group_docs]
                    out.append(result)
                docs = out
            elif "$sort" in stage:
                spec = stage["$sort"]
                for field, direction in reversed(list(spec.items())):
                    docs.sort(key=lambda d: (_get_nested(d, field) is None,
                                             _get_nested(d, field) or 0),
                              reverse=(direction == -1))
            elif "$project" in stage:
                spec = stage["$project"]
                docs = [{k: _get_nested(d, k) for k in spec if spec[k]}
                        for d in docs]
            elif "$limit" in stage:
                docs = docs[:stage["$limit"]]
        return docs

    def count(self, query: Optional[dict] = None) -> int:
        return len(self.find(query))

    def stats(self) -> dict:
        return {
            "name": self.name,
            "doc_count": len(self._docs),
            "indexes": list(self._indexes.keys()),
        }

def _set_nested(doc: dict, path: str, value: Any) -> None:
    """Set a value at a dot-notation path."""
    parts = path.split(".")
    cur = doc
    for part in parts[:-1]:
        if part not in cur or not isinstance(cur[part], dict):
            cur[part] = {}
        cur = cur[part]
    cur[parts[-1]] = value

class DocumentDB:
    """A document database with multiple collections."""

    def __init__(self):
        self._collections: Dict[str, Collection] = {}

    def get_collection(self, name: str) -> Collection:
        if name not in self._collections:
            self._collections[name] = Collection(name)
        return self._collections[name]

    def list_collections(self) -> List[str]:
        return list(self._collections.keys())

# ---------- Demo ----------
if __name__ == "__main__":
    print("=== Document Database demo (MongoDB-style) ===\n")
    db = DocumentDB()
    articles = db.get_collection("articles")

    print("--- Insert heterogeneous documents (schemaless) ---")
    articles.insert({
        "type": "blog", "title": "Intro to NoSQL",
        "body": "NoSQL is...", "tags": ["tech", "db"],
        "author": {"name": "alice", "id": 42},
        "views": 1500, "createdAt": "2024-01-15",
    })
    articles.insert({
        "type": "video", "title": "NoSQL Deep Dive",
        "duration": 300, "url": "https://...",
        "tags": ["tech", "video"],
        "author": {"name": "bob", "id": 17},
        "views": 8000, "createdAt": "2024-01-20",
    })
    articles.insert({
        "type": "blog", "title": "PostgreSQL Tips",
        "body": "Use EXPLAIN ANALYZE...", "tags": ["tech", "db", "postgres"],
        "author": {"name": "alice", "id": 42},
        "views": 3200, "createdAt": "2024-02-01",
    })
    articles.insert({
        "type": "gallery", "title": "Conference 2024",
        "images": [{"url": "img1.jpg"}, {"url": "img2.jpg"}],
        "tags": ["event"],
        "author": {"name": "carol", "id": 99},
        "views": 500, "createdAt": "2024-02-10",
    })
    print(f"  Inserted {articles.count()} heterogeneous docs")

    print("\n--- Query: find by type (uses index) ---")
    articles.create_index("type")
    for d in articles.find({"type": "blog"}):
        print(f"  blog: {d['title']} by {d['author']['name']}")

    print("\n--- Query: nested field (author.name) via dot notation ---")
    for d in articles.find({"author.name": "alice"}):
        print(f"  {d['title']} (views: {d['views']})")

    print("\n--- Query: array membership (tags: 'tech') ---")
    for d in articles.find({"tags": "tech"}):
        print(f"  {d['title']} tags={d['tags']}")

    print("\n--- Query: operator ($gt views > 2000) ---")
    for d in articles.find({"views": {"$gt": 2000}}):
        print(f"  {d['title']} views={d['views']}")

    print("\n--- Query: $or (blog OR video) ---")
    for d in articles.find({"$or": [{"type": "blog"}, {"type": "video"}]}):
        print(f"  {d['type']}: {d['title']}")

    print("\n--- Update: $inc views, $push tags ---")
    articles.update({"title": "Intro to NoSQL"},
                    {"$inc": {"views": 100}, "$push": {"tags": "popular"}})
    doc = articles.find_one({"title": "Intro to NoSQL"})
    print(f"  After update: views={doc['views']}, tags={doc['tags']}")

    print("\n--- Aggregation pipeline: group by author, sum views, sort desc ---")
    pipeline = [
        {"$match": {"type": "blog"}},
        {"$group": {"_id": "$author.name",
                    "total_views": {"$sum": "$views"},
                    "count": {"$sum": 1}}},
        {"$sort": {"total_views": -1}},
    ]
    for result in articles.aggregate(pipeline):
        print(f"  {result['_id']}: {result['count']} posts, "
              f"{result['total_views']} views")

    print("\n--- Aggregation: top 2 articles by views ---")
    pipeline = [
        {"$sort": {"views": -1}},
        {"$project": {"title": 1, "views": 1, "type": 1}},
        {"$limit": 2},
    ]
    for result in articles.aggregate(pipeline):
        print(f"  {result['title']} ({result['type']}): {result['views']}")

    print("\n--- Schemaless cautionary tale (Uber's lesson) ---")
    # Different teams use different field names for the same concept
    trips = db.get_collection("trips")
    trips.insert({"trip_id": "T1", "rider": "alice", "amount": 25.50})
    trips.insert({"tripId": "T2", "rider": "bob", "amount": 18.00})  # typo!
    trips.insert({"id": "T3", "rider": "carol", "amount": 32.00})    # different!
    print(f"  3 trips inserted, but with 3 different ID field names!")
    print(f"  find({{trip_id: 'T1'}}) = {trips.find_one({'trip_id': 'T1'})}")
    print(f"  find({{tripId: 'T2'}}) = {trips.find_one({'tripId': 'T2'})}")
    print(f"  find({{id: 'T3'}}) = {trips.find_one({'id': 'T3'})}")
    print("  -> Schemaless = schema is now YOUR problem")
    print("     (Mitigation: JSON Schema validator, app-level Pydantic,")
    print("      versioned docs with schema_version field)")

    print(f"\n=== Final stats ===")
    for name in db.list_collections():
        c = db.get_collection(name)
        print(f"  {c.stats()}")

    print("\n  Document DB trade-offs:")
    print("    + hierarchical data, schemaless (evolves fast)")
    print("    + nested queries via dot notation, aggregation pipeline")
    print("    + indexes on any field (incl. nested, arrays)")
    print("    - no joins (denormalize or $lookup, slower than RDBMS)")
    print("    - schemaless = schema-chaos without discipline")
    print("    - transactions limited (single-doc pre-4.0, multi-doc slow)")
    print("    - storage verbose (field names repeated per doc)")
    print("    Use when: hierarchical, schema evolves, joins rare")
    print("    Avoid when: relational, joins frequent, schema stable (Uber)")
